  const byCode = new Map(catalog.map(record => [String(record.testCode || '').trim(), record]));
  for (const record of verified) {
    const previous = byCode.get(record.testCode);
    if (!previous) catalog.push(record);
    else if (previous.status === 'pending') Object.assign(previous, record, { id: previous.id || record.id });
  }
  for (const [code, name, reason, status] of [
    ...holds.map(row => [...row, 'blocked']),
    ...references.map(row => [...row, 'pending'])
  ]) {
    const previous = byCode.get(code);
    if (previous && previous.status !== 'pending') continue;
    const record = {
      id: previous?.id || 'labcorp-compendium-hold-' + code,
      testCode: code,
      testName: name,
      status,
      specimenType: 'Verify specimen',
      drawContainer: status === 'blocked' ? 'Do Not Collect' : 'Verify Official Instructions',
      transportContainer: 'Verify Official Instructions',
      specialInstructions: (status === 'blocked' ? 'DO NOT PERFORM ONSITE. ' : 'DIRECTORY REFERENCE ONLY. ') + reason,
      source: 'https://cdos.halfpenny.com/labcorp/TestDisplay/' + code
    };
    if (previous) Object.assign(previous, record);
    else catalog.push(record);
  }
